<dialog id="ewt-payment-dialog" aria-labelledby="ewt-payment-title"><form id="ewt-payment-form"><header><h2 id="ewt-payment-title">Tag {{ $paymentTaxLabel ?? 'EWT' }} payment</h2><button type="button" data-ewt-close aria-label="Close payment dialog">×</button></header><p>Record a remittance already paid. This does not send money or file a return.</p><div class="ewt-fields"><label>Filing<select name="form">@if($monthlyOnly ?? false)<option value="1601-C">Monthly 1601-C</option>@else<option value="1601-EQ">Quarterly 1601-EQ</option><option value="0619-E">Monthly 0619-E</option>@endif</select></label><label>Period<select name="period" id="ewt-payment-period"></select></label><label>Payment date<input name="date" type="date" max="{{ now('Asia/Manila')->toDateString() }}" value="{{ now('Asia/Manila')->toDateString() }}" required></label><label>Total paid (PHP)<input name="amount" inputmode="decimal" pattern="([0-9]+|[0-9]{1,3}(,[0-9]{3})+)([.][0-9]{1,2})?" data-ewt-money required placeholder="0.00"></label><label>Penalty portion (PHP)<input name="penalty" inputmode="decimal" value="0.00" pattern="([0-9]+|[0-9]{1,3}(,[0-9]{3})+)([.][0-9]{1,2})?" data-ewt-money required></label><label>Method<select name="method">@foreach(['Cash','Check','eFPS','GCash','Tax Debit Memo','Other'] as $method)<option>{{ $method }}</option>@endforeach</select></label><label>Reference<input name="reference" maxlength="150"></label><label>Remarks<input name="remarks" maxlength="1000"></label><label class="ewt-check"><input name="post_now" type="checkbox">Post a payment journal now</label><label id="ewt-payable-field" hidden>{{ $paymentTaxLabel ?? 'EWT' }} payable account<select name="net_account">@foreach($summary['accounts'] as $account) @if($account['type'] === 'Liability')<option value="{{ $account['code'] }}" @selected($account['code'] === ($payableAccount ?? '2140'))>{{ $account['code'] }} — {{ $account['name'] }}</option>@endif @endforeach</select></label><label id="ewt-bank-field" hidden>Cash / bank account<select name="bank"><option value="">Choose account</option>@foreach($summary['accounts'] as $account) @if($account['is_cash_bank'])<option value="{{ $account['code'] }}">{{ $account['code'] }} — {{ $account['name'] }}</option>@endif @endforeach</select></label><label id="ewt-link-field">Existing posted journal (optional)<select name="linked_source"><option value="">Tag only — no journal</option>@foreach($summary['journals'] as $journal)<option value="{{ $journal->source_key }}">{{ $journal->number }} — {{ $journal->transaction_date }}</option>@endforeach</select></label><label id="ewt-penalty-field" hidden>Penalty expense account<select name="penalty_account"><option value="7290">7290 — Penalties &amp; Surcharges</option>@foreach($summary['accounts'] as $account) @if($account['type'] === 'Expense' && $account['code'] !== '7290')<option value="{{ $account['code'] }}">{{ $account['code'] }} — {{ $account['name'] }}</option>@endif @endforeach</select></label></div><div id="ewt-preview" hidden aria-live="polite"></div><p id="ewt-payment-error" role="alert"></p><footer><button type="button" class="button secondary compact" data-ewt-close>Cancel</button><button type="submit" class="button secondary compact" id="ewt-review">Preview payment</button><button type="button" class="button primary compact" id="ewt-confirm" hidden>Confirm payment record</button></footer></form></dialog>
